<script setup lang="ts">
import { computed,ref } from 'vue'
import { projectPlaces } from './types'
import PhotoGallery from './PhotoGallery.vue'
const props=withDefaults(defineProps<{article:any;selected?:string|null;available?:boolean}>(),{available:true}),emit=defineEmits<{(e:'select',id:string):void}>()
const visible=ref(true),points=computed(()=>projectPlaces(props.article.places)),chosen=computed(()=>props.article.places.find((p:any)=>p.id===props.selected)),photos=computed(()=>{const ids=new Set((props.article.life?.photos||[]).filter((p:any)=>p.place_id===props.selected).map((p:any)=>p.media_id));for(const a of props.article.life?.activities||[])if(a.place_id===props.selected)for(const id of a.media_ids)ids.add(id);return props.article.media.filter((p:any)=>ids.has(p.id))})
const enabled=computed(()=>props.article.life?.map_mode!=='hidden'&&visible.value&&props.available!==false)
</script>
<template><div class="place-map"><p class="map-privacy">离线地点示意图 · 无底图、无第三方请求。标记依据经纬度投影，不提供路线或导航。</p><button v-if="article.life?.map_mode!=='hidden'" class="map-toggle" @click="visible=!visible">{{visible?'仅看地点列表':'显示离线示意图'}}</button><svg v-if="enabled&&points.length" viewBox="0 0 800 400" role="group" aria-label="私人旅行地点示意图"><title>经纬度地点示意图，北方在上，无在线瓦片</title><rect x="1" y="1" width="798" height="398" rx="16" class="map-bg" /><path v-for="x in [100,200,300,400,500,600,700]" :key="'x'+x" :d="`M ${x} 0 V 400`" class="map-grid"/><path v-for="y in [100,200,300]" :key="'y'+y" :d="`M 0 ${y} H 800`" class="map-grid"/><text x="20" y="28">N ↑</text><g v-for="(p,i) in points" :key="p.id" tabindex="0" role="button" :aria-label="'地图地点：'+p.name" :aria-pressed="selected===p.id" @click="emit('select',p.id)" @keydown.enter.prevent="emit('select',p.id)" @keydown.space.prevent="emit('select',p.id)"><title>{{p.name}} · {{p.latitude}}, {{p.longitude}}</title><circle :cx="p.x" :cy="p.y" :r="selected===p.id?17:12" class="map-point"/><text :x="p.x+20" :y="p.y+5" class="map-label">{{i+1}}</text></g></svg><p v-else class="map-fallback" role="status">{{article.life?.map_mode==='hidden'?'作者已关闭地图。':'示意图未显示或没有可用坐标。'}}地点列表始终可读。</p>
<div class="map-place-list"><button v-for="(p,i) in article.places" :key="p.id" :aria-pressed="selected===p.id" @click="emit('select',p.id)"><strong>{{i+1}} · {{p.name}}</strong><span>{{[p.city,p.address].filter(Boolean).join(' · ')}}</span><small>{{p.latitude!=null?p.latitude+', '+p.longitude:'尚无经纬度'}}</small></button></div><section v-if="chosen" class="map-place-detail"><h3>{{chosen.name}}</h3><p>{{[chosen.country,chosen.region,chosen.city,chosen.address].filter(Boolean).join(' · ')}}</p><p class="plain-value">{{chosen.notes}}</p><PhotoGallery v-if="photos.length" :photos="photos" /></section></div></template>
<style scoped>
.place-map{margin:24px 0;overflow-wrap:anywhere}.map-privacy{font-size:14px}.place-map svg{width:100%;height:auto;display:block;margin:20px 0}.map-bg{fill:var(--reader-card-background,var(--surface));stroke:var(--reader-border,var(--line))}.map-grid{stroke:var(--reader-border,var(--line));stroke-dasharray:4 8;fill:none}.map-point{fill:var(--reader-accent,var(--accent));stroke:var(--reader-card-background,var(--surface));stroke-width:4}.place-map text{fill:var(--reader-body-text,var(--ink));font:20px system-ui}.place-map g{cursor:pointer}.place-map g:focus{outline:3px solid var(--reader-accent,var(--accent))}.map-place-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:12px}.map-place-list button{display:grid;gap:8px;text-align:left;white-space:normal;min-width:0;overflow-wrap:anywhere}.map-place-list [aria-pressed=true]{border:2px solid var(--reader-accent,var(--accent));background:var(--bg)}.map-place-list span,.map-place-list small{font-size:13px;color:var(--reader-muted-text,var(--muted))}.map-place-detail{margin:24px 0;padding:20px;border:1px solid var(--reader-border,var(--line));border-radius:var(--radius)}
</style>
